  render: (_args, value) => [{ type: 'text', text: clip(value) }],
}

function registerTools(ctx) {
  const tools = ctx.get ? ctx.get('tools') : ctx.tools
  if (!tools || typeof tools.register !== 'function') return []

  const disposers = []

  disposers.push(
    tools.register({
