            ok: false,
            error: res.ok ? '未能解析 JSON 输出' : '研究命令执行失败',
            stderr: tail(res.stderr),
            stdout: tail(res.stdout, 4000),
          }
        }
        return {
          ok: res.ok,
          topic,
          emit,
